  "plan.enterprisesSchools": "شركات المقاولات والمدارس — Smart Al-Idara Pro",
  "plan.enterprisesSchools.blurb":
    "999 درهم/شهر أو 8000 درهم/سنة — كل الأقسام مفتوحة: التعليم، المخزون، رادار التأشيرة، السيارات والعقارات، النقل، RH، وغيرها — بدون استثناء. / All modules unlocked: education, inventory, visa radar, cars & real estate, HR & more.",
  "plan.lawyers": "المحامون / Lawyers",
  "plan.lawyers.blurb":
    "599 درهم/شهر أو 5000 درهم/سنة — بوابة المحامي الاحترافي + صياغة المقالات القضائية + تتبع الملفات + المحرر القانوني الذكي. / Lawyer Portal, court filings, case tracking & smart legal editor.",
  "plan.librariesBase": "المكتبات — الأساسية / Libraries — Essential",
  "plan.librariesBase.blurb": "399 درهم/شهر أو 3830 درهم/سنة — المحرر الذكي والخدمات الحكومية. / Smart editor & government hub.",
  "plan.librariesPlus": "المكتبات — المتقدمة + التأشيرة / Libraries — Plus & visa",
  "plan.librariesPlus.blurb":
    "599 درهم/شهر أو 5000 درهم/سنة — كل أقسام الخطة مفتوحة بما فيها رادار التأشيرة والمخزون والمالية. / All plan modules unlocked including visa radar, inventory & accounting.",
  "plan.retail": "البقال والمحلات التجارية — الباقة العادية / Retail shops — Basic",
  "plan.retail.blurb": "399 درهم/شهر أو 3830 درهم/سنة — مخزون ومبيعات ومالية ومعاهد. / Stock, sales, finance & institutes tools.",
  "plan.retailPro": "البقال والمحلات التجارية — الباقة برو / Retail shops — Pro",
  "plan.retailPro.blurb": "799 درهم/شهر أو 7670 درهم/سنة — كل ما في الباقة العادية + رادار الطلبات والتوصيل. / All in Basic plan + delivery hub.",
  "plan.deliveryHubOnly": "رادار الطلبات والتوصيل — خطة خاصة / Delivery Hub — Standalone",
  "plan.deliveryHubOnly.blurb": "2500 درهم/شهر أو 24000 درهم/سنة — رادار الطلبات والتوصيل الكامل مع المراسلات. / Full delivery hub with messaging.",
  "plan.institutes": "المعاهد والمراكز / Training institutes",
  "plan.institutes.blurb":
    "299 درهم/شهر أو 2870 درهم/سنة — تعليم ذكي، أكاديمية، مراسلات، طباعة تعليمية. / Smart education, academy, messaging & prints.",
  "plan.accountants": "المحاسبون والخبراء الماليون / Accountants",
  "plan.accountants.blurb":
    "599 درهم/شهر أو 5000 درهم/سنة — تأسيس شركة، مكتبة قانونية، تتبع، تدريب، RH. / Company setup, legal library, tracking, academy, HR.",
  "plan.carsRealEstate": "قسم السيارات والعقارات / Cars & real estate",
  "plan.carsRealEstate.blurb":
    "399 درهم/شهر أو 3830 درهم/سنة — كراء وبيع السيارات، العقارات، العقود، الفواتير والتصدير. أو ضمن خطة 999 للشركات. / Cars & property — standalone 399 DH/mo or bundled in the 999 plan.",

