  "nav.legalTerms": "الشروط والحماية / Legal",
  "legal.termsTitle": "إخلاء مسؤولية وشروط الاستخدام",
  "legal.termsUpdated": "آخر تحديث: يناير 2026 — للمعلومات العامة فقط وليست استشارة قانونية.",
  "legal.termsIntro":
    "توضح هذه الصفحة حدود مسؤولية منصة Smart Al-Idara Pro وتستخدمها على مسؤوليتك الخاصة وفق القوانين المطبقة في المغرب عند الاقتضاء.",
  "legal.termsSection1": "1. طبيعة الخدمة",
  "legal.termsSection1Body":
    "المنصة تقدّم أدوات إدارية وتقارير ومساعدات ذكاء اصطناعي للمساعدة فقط. لا تُعدّ الاستجابات الآلية أو القوالب استشارة قانونية أو محاسبية أو ضريبية رسمية.",
  "legal.termsSection2": "2. مسؤولية المحتوى",
  "legal.termsSection2Body":
    "أنت مسؤول عن صحة البيانات التي تدخلها وتصدّرها. المنصة لا تضمن دقة مخرجات الطرف الثالث (مثل نماذج الذكاء الاصطناعي أو الروابط الخارجية).",
  "legal.termsSection3": "3. الخصوصية والأمان",
  "legal.termsSection3Body":
    "نطبّق ممارسات أمان معقولة. يُنصح بتخزين كلمات مرور قوية وعدم مشاركة جلسة الدخول. يمكن تشفير حقول حساسة على الخادم عند تفعيل مفتاح FIELD_ENCRYPTION_KEY.",
  "legal.termsSection4": "4. حدود المسؤولية",
  "legal.termsSection4Body":
    "إلى أقصى حد يسمح به القانون، لا تتحمل المنصة أو مالكوها المسؤولية عن أي أضرار غير مباشرة أو فقدان أرباح ناتج عن استخدام الخدمة.",
  "legal.termsFooter": "للاستفسارات القانونية الجدية استشر محامياً مؤهلاً في ولايتك القضائية.",

  "securityPage.title": "الأمان والخصوصية",
  "securityPage.updated": "آخر مراجعة: أبريل 2026",
  "securityPage.intro":
    "تلتزم منصّة Smart Al-Idara بتطبيق ممارسات أمان معقولة وتشفير الاتصالات (HTTPS) وحماية الجلسات. لا يُعدّ أي نظام خالياً تماماً من المخاطر؛ نعمل على التحديث المستمر.",
  "securityPage.encryption":
    "التشفير: يُنقل البيانات بين متصفحك وخوادمنا عبر قنوات مشفّرة وفق بروتوكولات حديثة. كلمات المرور لا تُخزَّن بنص صريح على الخادم (هاش آمن).",
  "securityPage.supabase":
    "المصادقة: عند تفعيل Supabase Auth، تُدار الجلسات والهوية عبر بنية موثوقة؛ يمكن تفعيل تسجيل الدخول الاجتماعي (Google، Facebook، Apple، TikTok حسب الإعداد) من لوحة المشروع.",
  "securityPage.rateLimit":
    "مكافحة الإساءة: يُطبَّق حدٌّ لمحاولات تسجيل الدخول والتسجيل على الخادم (rate limiting) وللحدّ من الروبوتات؛ يُكمّل ذلك حماية من طرف مزوّد الاستضافة.",
  "securityPage.injection":
    "حقن SQL و XSS: واجهة الويب مبنية على React (هروب افتراضي للنصوص)؛ استعلامات قاعدة البيانات مُجهَّزة (prepared statements) لتقليل مخاطر حقن SQL.",
  "securityPage.footer":
    "للتفاصيل القانونية الكاملة راجع صفحة الشروط وصفحة حماية المعطيات (CGU).",

  "cguPage.title": "الشروط العامة للاستخدام (CGU)",
  "cguPage.updated": "نسخة إرشادية — أبريل 2026 — تتضمن مراجعاً إلى القانون 09-08",
  "cguPage.s1": "1. الهوية والغرض",
  "cguPage.s1b":
    "توفر Smart Al-Idara منصّة برمجية (SaaS) لإدارة المهام والوثائق والتكوين؛ الاستخدام يخضع لهذه الشروط والتشريع المغربي عند الاقتضاء.",
  "cguPage.s2": "2. المعطيات ذات الطابع الشخصي (القانون 09-08)",
  "cguPage.s2b":
    "تُعالَج المعطيات الشخصية بشكل مشروع ومحصور في الأغراض المعلومة (إدارة الحساب، الفوترة، الدعم). يمكن للمستخدم ممارسة حقوقه (الاطلاع، التصحيح، الاعتراض) عبر التواصل الرسمي للمنصّة.",
  "cguPage.s3": "3. الاستخدام المقبول",
  "cguPage.s3b":
    "يُمنع إساءة استخدام الخدمة (إرسال غير قانوني، محاولات اختراق، إرهاب معلوماتي). يُحتفظ بحق تعليق الحساب عند مخالفة جسيمة.",
  "cguPage.s4": "4. المسؤولية والقانون الواجب التطبيق",
  "cguPage.s4b":
    "المنصّة تُقدَّم «كما هي» ضمن حدود المسؤولية المنصوص عليها في الوثائق القانونية. تُحال النزاعات — عند الاقتضاء — إلى المحاكم المختصة في المغرب.",
  "cguPage.footer":
    "هذه الصفحة معلوماتية ولا تغني عن استشارة محامٍ؛ راجع النصوص الرسمية والتحديثات التشريعية.",

  "trustPage.title": "ميثاق الثقة",
  "trustPage.subtitle": "التزامنا بالشباب والإدارة والتعلّم الرقمي في المغرب",
  "trustPage.p1":
    "تهدف المنصّة إلى تسهيل الوصول إلى أدوات عمل واقعية: التوظيف والموارد البشرية، المساعدة في المساطر الإدارية، وتعلّم البرمجة والمهارات الرقمية لفائدة الشباب المغربي.",
  "trustPage.p2":
    "نؤمن بالشفافية في التسعير، والدعم البشري عبر القنوات الرسمية، واحترام خصوصية المستخدمين وفق القانون 09-08 والمعايير الدولية المعترف بها في مجال حماية البيانات.",
  "trustPage.p3": "هذا الميثاق يعبّر عن قيمنا؛ التفاصيل التعاقدية مذكورة في الاشتراك والوثائق القانونية المرافقة.",

