  "guide.processing": "Processing...",
  "guide.defaultResponse": "I'm here to help you understand how to use Smart Al-Idara Pro.\n\nYou can ask me about:\n- How to subscribe to the platform\n- How to use any section\n- How to add data\n- How to use different features\n\n**Available sections:**\n- HR (Human Resources)\n- Inventory (Stock)\n- Visa Radar\n- Law\n- Education\n- Real Estate\n- Business Tools\n\nWhat would you like to know?",
  "guide.generalQuestion": "Welcome to Smart Al-Idara Pro!\n\nI'm your personal assistant to learn how to use the platform. You can ask me about:\n\n**Available sections:**\n- Human Resources (HR)\n- Inventory & POS\n- Visa Radar\n- Law\n- Education\n- Real Estate\n- Business Tools\n\n**Common questions:**\n- 'How do I subscribe to the platform?'\n- 'How do I use the HR section?'\n- 'How do I add a new product?'\n- 'How do I monitor visa appointments?'\n- 'How do I manage legal cases?'\n\n**What would you like to know?**",
  "guide.alreadySubscribed": "**You are already subscribed!**\n\nYour account is active and you can use all subscribed sections. If you want to:\n- Renew subscription: Go to the subscriptions section\n- Change plan: Contact technical support\n- Add new sections: Go to subscriptions section and choose additional sections",
  "guide.hrSection": "**Human Resources (HR) Section:**\n\nThis section helps you manage employees and workers efficiently:\n\n**Key features:**\n1. **Employee management:** Add and edit employee information (name, employee ID, salary, contract date)\n2. **Attendance tracking:** Record employee check-in/out and calculate working hours\n3. **Payroll management:** Calculate salaries based on working hours and performance\n4. **Reports:** Generate comprehensive reports about employees and performance\n\n**How to use:**\n1. Go to the HR section from the sidebar\n2. Click 'Add employee' to add a new employee\n3. Fill in the required information (name, employee ID, salary, etc.)\n4. Save the data\n5. You can edit or delete employees at any time\n\n**Tips:**\n- Use unique employee IDs for each employee\n- Specify contract dates accurately for salary calculation\n- Review reports regularly to track performance",
  "guide.inventorySection": "**Inventory & POS Section:**\n\nThis section helps you manage inventory and sales operations:\n\n**Key features:**\n1. **Product management:** Add and edit products (name, price, quantity, minimum alert threshold)\n2. **Point of Sale (POS):** Sell products quickly and easily\n3. **Inventory tracking:** Automatic alerts when stock is low\n4. **Reports:** Sales and inventory reports\n5. **Data export:** Export reports in PDF or Excel format\n\n**How to use:**\n1. Go to the Inventory section from the sidebar\n2. **Add product:** Click 'Add product' and fill in the information\n3. **Sales:** Go to the 'Quick sale' tab and select products\n4. **Inventory:** Monitor stock quantity and alerts\n\n**Tips:**\n- Set minimum stock threshold to get alerts\n- Use barcode scanning for speed\n- Review sales reports regularly",
  "guide.visaSection": "**Visa Radar Section:**\n\nThis section helps you monitor visa appointment dates:\n\n**Key features:**\n1. **Center monitoring:** Monitor different visa centers\n2. **Instant alerts:** Notifications when new appointments are available\n3. **Pattern tracking:** Analyze appointment availability patterns\n4. **Operation log:** Complete log of operations and alerts\n\n**How to use:**\n1. Go to the Visa Radar section from the sidebar\n2. Choose the centers you want to monitor\n3. Enable alerts\n4. Watch for notifications when new appointments are available\n\n**Tips:**\n- Enable alerts to get instant notifications\n- Monitor availability patterns to improve your chances\n- Check the log regularly",
  "guide.lawSection": "**Law Section:**\n\nThis section helps you manage legal cases and documents:\n\n**Key features:**\n1. **Case management:** Add and edit cases (title, client name, deadline)\n2. **Document tracking:** Organize legal documents\n3. **Accounting reports:** Track expenses and revenues\n4. **Alerts:** Reminders for deadlines\n\n**How to use:**\n1. Go to the Law section from the sidebar\n2. Click 'Add case' to create a new case\n3. Fill in the required information\n4. Add relevant documents\n5. Monitor alerts and deadlines",
  "guide.eduSection": "**Education Section:**\n\nThis section helps you manage educational institutions:\n\n**Key features:**\n1. **Student management:** Add and edit student data\n2. **Attendance tracking:** Record student attendance\n3. **Grades:** Manage grades and evaluations\n4. **Reports:** Comprehensive reports about students and performance\n\n**How to use:**\n1. Go to the Education section from the sidebar\n2. Add students and basic information\n3. Record attendance and grades regularly\n4. Monitor reports to track progress",
  "guide.realEstateSection": "**Real Estate Section:**\n\nThis section helps you manage real estate and properties:\n\n**Key features:**\n1. **Property management:** Add and edit property information\n2. **Transaction tracking:** Record sales and purchase operations\n3. **Clients:** Manage potential client data\n4. **Reports:** Reports on performance and sales\n\n**How to use:**\n1. Go to the Real Estate section from the sidebar\n2. Add properties with full details\n3. Record transactions and dealings\n4. Monitor reports to track performance",
  "guide.businessToolsSection": "**Business Tools Section:**\n\nThis section provides useful tools for managing your business:\n\n**Key features:**\n1. **Notepad:** Take notes and tasks\n2. **Calendar:** Organize appointments and meetings\n3. **Reports:** Create custom reports\n4. **Export:** Export data in different formats\n\n**How to use:**\n1. Go to the Business Tools section from the sidebar\n2. Choose the tool you need\n3. Use the tool according to your needs\n4. Save data for later reference",
  "guide.subscriptionInfo": "**How to subscribe to Smart Al-Idara Pro:**\n\n1. **Registration:** Create a new account using your email\n2. **Choose plan:** Select the plan suitable for your needs\n3. **Payment:** Choose the appropriate payment method (bank transfer, CIH, Cash Plus, or credit recharge)\n4. **Send receipt:** Attach the payment receipt and wait for approval\n5. **Activation:** After approval, your account will be activated immediately\n\n**Available plans:**\n\n🏢 **Construction Companies & Schools — Smart Al-Idara Pro**\n999 MAD/month or 8000 MAD/year — All sections open: Education, Inventory, Visa Radar, Cars & Real Estate, Transport, HR, and more — without exception.\n\n⚖️ **Lawyers**\n599 MAD/month or 5000 MAD/year — Professional lawyer portal + legal article drafting + file tracking + smart legal editor.\n\n📚 **Libraries — Essential**\n399 MAD/month or 3830 MAD/year — Smart editor and government services.\n\n📚 **Libraries — Plus & Visa**\n599 MAD/month or 5000 MAD/year — All plan sections open including Visa Radar, Inventory, and Finance.\n\n🚗 **Cars & Real Estate Section**\n399 MAD/month or 3830 MAD/year — Car rental and sales, real estate, contracts, invoices, and export. Or included in the 999 plan for companies.\n\n🏪 **Retail Shops — Basic**\n399 MAD/month or 3830 MAD/year — Inventory, sales, finance, and institutes.\n\n🏪 **Retail Shops — Pro**\n799 MAD/month or 7670 MAD/year — Everything in Basic + Order Radar and Delivery.\n\n🎓 **Training Institutes**\n299 MAD/month or 2870 MAD/year — Smart education, academy, correspondence, educational printing.\n\n💰 **Accountants & Financial Experts**\n599 MAD/month or 5000 MAD/year — Company formation, legal library, tracking, training, HR.\n\nYou can also try the platform for free for 7 days!",
