  "securityPage.title": "Security & privacy",
  "securityPage.updated": "Last reviewed: April 2026",
  "securityPage.intro":
    "Smart Al-Idara applies reasonable security practices, encrypted transport (HTTPS), and session protection. No system is risk-free; we continuously improve controls.",
  "securityPage.encryption":
    "Encryption: data in transit is protected with modern TLS. Passwords are not stored in plain text on our servers (secure hashing).",
  "securityPage.supabase":
    "Authentication: with Supabase Auth enabled, identity and sessions are handled by a robust stack; social login (Google, Facebook, Apple, TikTok per configuration) is enabled from the Supabase project.",
  "securityPage.rateLimit":
    "Abuse protection: login and registration endpoints are rate-limited on the server; hosting/CDN layers add further protection.",
  "securityPage.injection":
    "SQL injection & XSS: the UI is built with React (default escaping); database access uses parameterized queries to reduce SQL injection risk.",
  "securityPage.footer": "For full legal wording, see Terms and the CGU / data-protection sections.",

