  "cguPage.updated": "Indicative version — April 2026 — references Law 09-08",
  "cguPage.s1": "1. Identity and purpose",
  "cguPage.s1b":
    "Smart Al-Idara provides SaaS tools for administration, documents, and learning; use is governed by these terms and Moroccan law where applicable.",
  "cguPage.s2": "2. Personal data (Law 09-08)",
  "cguPage.s2b":
    "Personal data is processed lawfully and limited to stated purposes (account, billing, support). Users may exercise their rights (access, rectification, objection) via official contact channels.",
  "cguPage.s3": "3. Acceptable use",
  "cguPage.s3b":
    "You must not misuse the service (unlawful content, hacking, abuse). We may suspend accounts for serious breaches.",
  "cguPage.s4": "4. Liability and applicable law",
