export const STRINGS: Record<AppLocale, Dict> = {
  "ar-MA": arMA,
  "ar-SA": arSA,
  en,
  fr,
  es,
};

/** Every lookup is normalized to Western digits 0–9 (U+0030–39), regardless of OS locale. */
export function translate(locale: AppLocale, key: string): string {
  const raw = STRINGS[locale][key] ?? STRINGS.en[key] ?? key;
  return toWesternDigits(String(raw));
}
